INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (412, 66, 1, '﴿ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ ﴾', 1, 'أولًا: من القرآن الكريم. [الأنعام: ٩٠]. (ص227)', '', '', '﴿ أولئك ٱلذين هدى ٱللهۖ فبهدىهم ٱقۡتدهۡۗ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (413, 66, 2, '﴿ سَمِعۡنَا وَأَطَعۡنَاۚ ﴾', 1, 'ما يقول من دُعِيَ إلى حكم الله ورسوله. [النور: ٥١]. (ص227)', '', '', '﴿ سمعۡنا وأطعۡناۚ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (414, 66, 3, '﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾', 1, 'ما يقول الداعي إذا لم يُتَّبَعْ. [التوبة: ١٢٩]. (ص227)', '', '', '﴿ حسۡبي ٱلله لا إله إلا هوۖ عليۡه توكلۡتۖ وهو رب ٱلۡعرۡش ٱلۡعظيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (415, 66, 4, '﴿ مَعَاذَ ٱللَّهِۖ ﴾', 1, 'ما يقول إذا دُعِيَ إلى فعلٍ مُحَرَّمٍ. [يوسف: ٢٣]. (ص228)', '', '', '﴿ معاذ ٱللهۖ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (416, 66, 5, '﴿ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴾', 1, 'ما يقول إذا دُعِيَ إلى فعلٍ مُحَرَّمٍ. [الزمر: ١٣]. (ص228)', '', '', '﴿ إني أخاف إنۡ عصيۡت ربي عذاب يوۡم عظيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (417, 66, 6, '﴿ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴾', 1, 'ما يقول إذا دُعِيَ إلى فعلٍ مُحَرَّمٍ. [المائدة: ٢٨]. (ص228)', '', '', '﴿ إني أخاف ٱلله رب ٱلۡعلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (418, 66, 7, 'إنْ شاءَ اللهُ', 1, 'ما يقول إذا قال لشيءٍ: إنِّي فاعلٌ ذلكَ غدًا. [انظر سورة الكهف: ٢٣، ٢٤]. (ص228)', '', '', 'إن شاء الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (419, 66, 8, '﴿ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ ﴾', 1, 'ما يقول إذا رُزِقَ رزقًا وفيرًا، وسُئِلَ عنه. [آل عمران: ٣٧]. (ص228)', '', '', '﴿ هو منۡ عند ٱللهۖ إن ٱلله يرۡزق من يشاء بغيۡر حساب ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1528, 66, 9, 'وإذا حدثت له نعمةٌ أو كرامةٌ، قال:', 0, 'ما يقول إذا رُزِقَ رزقًا وفيرًا، وسُئِلَ عنه. (ص229)', '', '', 'وإذا حدثت له نعمة أو كرامة قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (420, 66, 10, '﴿ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ ﴾', 1, 'ما يقول إذا رُزِقَ رزقًا وفيرًا، وسُئِلَ عنه. [النمل: ٤٠]. (ص229)', '', '', '﴿ هذا من فضۡل ربي ليبۡلوني ءأشۡكر أمۡ أكۡفرۖ ومن شكر فإنما يشۡكر لنفۡسهۦۖ ومن كفر فإن ربي غني كريم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (421, 66, 11, '﴿ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ ﴾', 1, 'ما يقول إذا رُزِقَ رزقًا وفيرًا، وسُئِلَ عنه. [النمل: ١٩]. (ص229)', '', '', '﴿ رب أوۡزعۡني أنۡ أشۡكر نعۡمتك ٱلتي أنۡعمۡت علي وعلى ولدي وأنۡ أعۡمل صلحا ترۡضىه وأدۡخلۡني برحۡمتك في عبادك ٱلصلحين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (422, 66, 12, '﴿ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ﴾', 1, 'ما يقول عند مجادلة أهل الكتاب. [العنكبوت: ٤٦]. (ص229)', '', '', '﴿ ءامنا بٱلذي أنزل إليۡنا وأنزل إليۡكمۡ وإلهنا وإلهكمۡ وحد ونحۡن لهۥ مسۡلمون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (423, 66, 13, '﴿ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ ﴾', 1, 'ما يقول عند مجادلة أهل الكتاب. [آل عمران: ٦٤]. (ص229)', '', '', '﴿ يأهۡل ٱلۡكتب تعالوۡا إلى كلمة سواءۭ بيۡننا وبيۡنكمۡ ألا نعۡبد إلا ٱلله ولا نشۡرك بهۦ شيۡا ولا يتخذ بعۡضنا بعۡضا أرۡبابا من دون ٱللهۚ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (424, 66, 14, 'QuranText[(3:70:71)]', 1, 'ما يقول عند مجادلة أهل الكتاب. [آل عمران: ٧٠، ٧١]. (ص230)', '', '', '37071', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (425, 66, 15, '﴿ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ ٨٥ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', 1, 'كيف يدعو من ظلمه قومٌ؟ [يونس: ٨٥، ٨٦]. (ص230)', '', '', '﴿ على ٱلله توكلۡنا ربنا لا تجۡعلۡنا فتۡنة للۡقوۡم ٱلظلمين ٨٥ ونجنا برحۡمتك من ٱلۡقوۡم ٱلۡكفرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (426, 66, 16, 'رَبِّ إِنِّي ﴿ مَغۡلُوبٞ فَٱنتَصِرۡ ﴾', 1, 'كيف يدعو من ظلمه قومٌ؟ [القمر: ١٠]. (ص230)', '', '', 'رب إني ﴿ مغۡلوب فٱنتصرۡ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (427, 66, 17, '﴿ رَبِّ ٱنصُرۡنِي عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِينَ ﴾', 1, 'كيف يدعو من ظلمه قومٌ؟ [العنكبوت: ٣٠]. (ص230)', '', '', '﴿ رب ٱنصرۡني على ٱلۡقوۡم ٱلۡمفۡسدين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (428, 66, 18, '﴿ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ﴾', 1, 'ما يقول إذا بلغ أربعين سنة. [الأحقاف: ١٥]. (ص231)', '', '', '﴿ رب أوۡزعۡني أنۡ أشۡكر نعۡمتك ٱلتي أنۡعمۡت علي وعلى ولدي وأنۡ أعۡمل صلحا ترۡضىه وأصۡلحۡ لي في ذريتيۖ إني تبۡت إليۡك وإني من ٱلۡمسۡلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (429, 66, 19, '﴿ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ﴾', 1, 'ما يقول إذا استحفظ رجلًا ابنَه أو غيرَه. [يوسف: ٦٤]. (ص231)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (430, 66, 20, '﴿ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ﴾', 1, 'ما يقول من بُهِتَ بما ليس فيه. [يوسف: ١٨]. (ص232)', '', '', '﴿ فصبۡر جميلۖ وٱلله ٱلۡمسۡتعان على ما تصفون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1529, 66, 21, 'وإذا سمع رجلًا يقذِفُ عِرْضَ أخيه بدون بَيِّنَةٍ تستوفي نِصابَ وشروطَ الشهادةِ عليه -قال:', 0, 'ما يقول من بُهِتَ بما ليس فيه. (ص232)', '', '', 'وإذا سمع رجلا يقذف عرض أخيه بدون بينة تستوفي نصاب وشروط الشهادة عليه -قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (431, 66, 22, '﴿ هَٰذَآ إِفۡكٞ مُّبِينٞ ﴾', 1, 'ما يقول من بُهِتَ بما ليس فيه. [النور: ١٢]. (ص232)', '', '', '﴿ هذا إفۡك مبين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (432, 66, 23, '﴿ مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ﴾', 1, 'ما يقول من بُهِتَ بما ليس فيه. [النور: ١٦]. (ص232)', '', '', '﴿ ما يكون لنا أن نتكلم بهذا سبۡحنك هذا بهۡتن عظيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1530, 67, 1, 'إذا أخبره رجل أنه يُحِبُّه في الله، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'إذا أخبره رجل أنه يحبه في الله قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (433, 67, 2, 'أحبَّكَ الذي أحبَبتَني لهُ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'أحبك الذي أحببتني له', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1531, 67, 3, 'فإنْ كان هو أيضًا يُحِبُّه في الله، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'فإن كان هو أيضا يحبه في الله قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (434, 67, 4, 'وأنا واللهِ يا (فلان) أُحِبُّكَ في اللهِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'وأنا والله يا فلان أحبك في الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1532, 67, 5, 'وإذا رأى أخاه المسلم يضحك، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'وإذا رأى أخاه المسلم يضحك قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (435, 67, 6, 'أضحَكَ اللهُ سِنَّكَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'أضحك الله سنك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1533, 67, 7, 'وإذا عرض عليه أخوه من أهله وماله، قال له:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'وإذا عرض عليه أخوه من أهله وماله قال له', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (436, 67, 8, 'بارَكَ اللهُ لكَ في أهلِكَ ومالِكَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'بارك الله لك في أهلك ومالك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1534, 67, 9, 'وإذا قيل له: غَفَرَ اللهُ لك، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'وإذا قيل له غفر الله لك قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (437, 67, 10, 'ولَكَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'ولك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1535, 67, 11, 'وإذا ناداه شخصٌ، أجابه بقوله:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'وإذا ناداه شخص أجابه بقوله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (438, 67, 12, 'لَبَّيكَ أو: لبَّيكَ وسَعْدَيكَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص233)', '', '', 'لبيك أو لبيك وسعديك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1536, 67, 13, 'وإذا سَمِعَ رجلًا يمدح رجلًا في وجهه، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'وإذا سمع رجلا يمدح رجلا في وجهه قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (439, 67, 14, 'أمسِكْ، لا تُسمِعْهُ فتُهلِكَهُ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'أمسك لا تسمعه فتهلكه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (440, 67, 15, 'أو: وَيحَكَ! قَطَعتَ عُنُقَ صاحبِكَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'أو ويحك! قطعت عنق صاحبك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1537, 67, 16, 'أو: أهلكتُم -أو: قطعتُم- ظهرَ الرجل', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'أو أهلكتم -أو قطعتم- ظهر الرجل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1538, 67, 17, 'أو: عقرتَ الرجلَ، عقرك الله', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'أو عقرت الرجل عقرك الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1539, 67, 18, 'أو: المدحُ ذَبْحٌ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'أو المدح ذبح', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1540, 67, 19, 'وإذا كان مادِحًا أخاه لا محالة، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'وإذا كان مادحا أخاه لا محالة قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (441, 67, 20, 'أحسَبُهُ كذا، واللهُ حَسيبُهُ، ولا أُزَكِّي على اللهِ أحدًا', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'أحسبه كذا والله حسيبه ولا أزكي على الله أحدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1541, 67, 21, 'وكان الرجل من أصحاب النبي ﷺ إذا زُكِّيَ؛ قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'وكان الرجل من أصحاب النبي إذا زكي قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (442, 67, 22, 'اللهمَّ لا تؤاخِذْني بما يقولونَ، واغفِرْ لي ما لا يعلمونَ، واجعَلْني خيرًا ممَّا يظُنّونَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'اللهم لا تؤاخذني بما يقولون واغفر لي ما لا يعلمون واجعلني خيرا مما يظنون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1542, 67, 23, 'وإذا رأى قومًا على عملٍ صالحٍ، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'وإذا رأى قوما على عمل صالح قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (443, 67, 24, 'اعمَلوا، فإنَّكم على عملٍ صالحٍ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص234)', '', '', 'اعملوا فإنكم على عمل صالح', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1543, 67, 25, 'وإذا سَمِعَ كلمةً أعجبتْه، قال لقائلها:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'وإذا سمع كلمة أعجبته قال لقائلها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (444, 67, 26, 'أخذنا فألَكَ من فيكَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'أخذنا فألك من فيك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1544, 67, 27, 'وإذا بُشِّرَ بما يَسُرُّه، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'وإذا بشر بما يسره قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (445, 67, 28, 'الحمدُ للهِ، اللهُ أكبرُ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'الحمد لله الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1545, 67, 29, 'وإذا سَمِعَ من يغتاب رجلًا صالحًا؛ قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'وإذا سمع من يغتاب رجلا صالحا قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (446, 67, 30, 'بئسَ ما قلتَ! واللهِ ما عَلِمنا عليهِ إلا خيرًا', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'بئس ما قلت! والله ما علمنا عليه إلا خيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1546, 67, 31, 'وإذا تعجَّبَ، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'وإذا تعجب قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (447, 67, 32, '﴿ سُبۡحَانَ رَبِّي ﴾', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. [الإسراء: ٩٣]. (ص235)', '', '', '﴿ سبۡحان ربي ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1547, 67, 33, 'أو: لا إله إلا الله', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'أو لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1548, 67, 34, 'أو: سبحان الله', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'أو سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1549, 67, 35, 'أو: الله أكبر', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'أو الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1550, 67, 36, 'ويقول العالِمُ إذا أتاه طالِبُ العلم:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'ويقول العالم إذا أتاه طالب العلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (448, 67, 37, 'مرحبًا بوصيةِ رسولِ اللهِ ﷺ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'مرحبا بوصية رسول الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1551, 67, 38, 'وإذا أقسم، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'وإذا أقسم قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (449, 67, 39, 'لا، ومُقَلِّبِ القلوبِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'لا ومقلب القلوب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1552, 67, 40, 'أو: لا، ومُصَرِّفِ القلوب', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'أو لا ومصرف القلوب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1553, 67, 41, 'أو: والذي نفسي بيده', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص235)', '', '', 'أو والذي نفسي بيده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1554, 67, 42, 'وإذا غَضِبَ، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)', '', '', 'وإذا غضب قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (450, 67, 43, 'أعوذُ باللهِ من الشيطانِ الرجيمِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1555, 67, 44, 'أو: أعوذُ باللهِ السميعِ العليمِ من الشيطانِ الرجيمِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)', '', '', 'أو أعوذ بالله السميع العليم من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (451, 67, 45, 'أو: أعوذُ باللهِ السميعِ العليمِ من الشيطانِ الرجيمِ، مِنْ هَمْزِهِ ونَفْخِهِ ونَفْثِهِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1556, 67, 46, 'وإذا رأى ما يحب، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)', '', '', 'وإذا رأى ما يحب قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (452, 67, 47, 'الحمدُ للهِ الذي بِنِعمَتِهِ تَتِمُّ الصالحاتُ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)', '', '', 'الحمد لله الذي بنعمته تتم الصالحات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1557, 67, 48, 'وإذا رأى ما يكره، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)', '', '', 'وإذا رأى ما يكره قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (453, 67, 49, 'الحمدُ للهِ على كلِّ حالٍ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)', '', '', 'الحمد لله على كل حال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1558, 67, 50, 'ويقول في الفتنة:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص236)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (454, 67, 51, '﴿ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴾، اهدِني لِما اختُلِفَ فيهِ من الحقِّ بإذنِكَ، إنَّكَ تهدي مَنْ تشاءُ إلى صراطٍ مستقيمٍ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. [الزمر: ٤٦]. (ص236–237)', '', '', '﴿ ٱللهم فاطر ٱلسموت وٱلۡأرۡض علم ٱلۡغيۡب وٱلشهدة أنت تحۡكم بيۡن عبادك في ما كانوا فيه يخۡتلفون ﴾ اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (455, 67, 52, 'اللهمَّ إنِّي أسألُكَ العافيةَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'اللهم إني أسألك العافية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (456, 67, 53, 'أعوذُ باللهِ من الفِتَنِ، ما ظهَرَ منها وما بطَنَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'أعوذ بالله من الفتن ما ظهر منها وما بطن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (457, 67, 54, 'رَضينا باللهِ ربًّا، وبالإسلامِ دينًا، وبمحمدٍ رسولًا، نعوذُ باللهِ من سوءِ الفِتَنِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'رضينا بالله ربا وبالإسلام دينا وبمحمد رسولا نعوذ بالله من سوء الفتن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (458, 67, 55, 'اللهمَّ سَلِّمْني، وسَلِّمْ مِنِّي', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. [موقوف عن ابن عمر رضي الله عنهما – ضعيف]. (ص237)', '', '', 'اللهم سلمني وسلم مني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (459, 67, 56, 'اللهمَّ إنّا نعوذُ بِكَ أنْ نَرجِعَ على أعقابِنا، أو نُفتَنَ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. [التابعي ابن أبي مُلَيكة]. (ص237)', '', '', 'اللهم إنا نعوذ بك أن نرجع على أعقابنا أو نفتن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1559, 67, 57, 'وإذا أسدى شخصٌ إليه معروفًا، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'وإذا أسدى شخص إليه معروفا قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (460, 67, 58, 'جزاكَ اللهُ خيرًا', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'جزاك الله خيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1560, 67, 59, 'ويدعو له:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'ويدعو له', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (461, 67, 60, 'اللهمَّ فَقِّهْهُ في الدينِ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص237)', '', '', 'اللهم فقهه في الدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (462, 67, 61, 'اللهمَّ أكثِرْ مالَهُ ووَلَدَهُ، وبارِكْ لهُ فيما أعطيتَهُ', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص238)', '', '', 'اللهم أكثر ماله وولده وبارك له فيما أعطيته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1561, 67, 62, 'وإذا رأى مُبتلًى بمرضٍ أو غيره، قال:', 0, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص238)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (463, 67, 63, 'الحمدُ للهِ الذي عافاني ممَّا ابتلَاكَ بهِ، وفَضَّلَني على كثيرٍ من خَلْقِهِ تفضيلًا', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص238)', '', '', 'الحمد لله الذي عافاني مما ابتلاك به وفضلني على كثير من خلقه تفضيلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1562, 67, 64, 'أو: الحمدُ للهِ الذي عافاني ممَّا ابتلاكَ بهِ، وفَضَّلَني عليكَ، وعلى كثيرٍ من عبادِهِ تَفْضِيلًا', 1, 'ثانيًا: أذكار متفرِّقة من السُّنَّة الشَّريفة. (ص238)', '', '', 'أو الحمد لله الذي عافاني مما ابتلاك به وفضلني عليك وعلى كثير من عباده تفضيلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (464, 67, 65, 'بارَكَ اللهُ لكَ في أهلِكَ ومالِكَ', 1, 'ما يقول إذا أدَّى مالًا كان اقترضه. (ص239)', '', '', 'بارك الله لك في أهلك ومالك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1563, 67, 66, 'جزاكَ اللهُ خيرًا', 1, 'ما يقول إذا أدَّى مالًا كان اقترضه. (ص239)', '', '', 'جزاك الله خيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (465, 67, 67, 'أَوْفَيْتَنِي، أَوْفَى اللهُ بِكَ', 1, 'ما يقول إذا استوفى دَيْنَه. (ص239)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1564, 67, 68, 'يضع يده على ناصيتها، ويُسَمِّي الله عَزَّ وَجَلَّ، ويدعو بالبركة، ويقول:', 0, 'ما يقول إذا اشترى دابَّةً ونحوَها. (ص239)', '', '', 'يضع يده على ناصيتها ويسمي الله عز وجل ويدعو بالبركة ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (466, 67, 69, 'اللهمَّ إنِّي أسألُكَ من خيرِها، وخيرِ ما جَبَلتَها عليهِ، وأعوذُ بِكَ من شرِّها، وشرِّ ما جَبَلتَها عليهِ', 1, 'ما يقول إذا اشترى دابَّةً ونحوَها. (ص239)', '', '', 'اللهم إني أسألك من خيرها وخير ما جبلتها عليه وأعوذ بك من شرها وشر ما جبلتها عليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1565, 67, 70, 'يضعها على عينيه، ثم على شفتيه، ثم يقول:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص240)', '', '', 'يضعها على عينيه ثم على شفتيه ثم يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (467, 67, 71, 'اللهمَّ بارِكْ لنا في ثَمَرِنا، وبارِكْ لنا في مَدينَتِنا، وبارِكْ لنا في صاعِنا، وبارِكْ لنا في مُدِّنا، بركةً معَ بركةٍ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص240)', '', '', 'اللهم بارك لنا في ثمرنا وبارك لنا في مدينتنا وبارك لنا في صاعنا وبارك لنا في مدنا بركة مع بركة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1566, 67, 72, 'ثُمَّ يدعو أصغرَ وليدٍ يكون عنده، فيعطيه ذلك الثمر.', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص240)', '', '', 'ثم يدعو أصغر وليد يكون عنده فيعطيه ذلك الثمر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1567, 67, 73, 'وإذا رأى من نفسِه أو وَلَدِه أو مَالِه أو غَيْرِ ذلك شيئًا فأعجبه، وخاف أن يُصيبَه بعينِه، أو يتضرَّرَ بذلِكَ، قال:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص240)', '', '', 'وإذا رأى من نفسه أو ولده أو ماله أو غير ذلك شيئا فأعجبه وخاف أن يصيبه بعينه أو يتضرر بذلك قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (468, 67, 74, '﴿ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ ﴾', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. [الكهف: ٣٩]. (ص240)', '', '', '﴿ ما شآء ٱلله لا قوة إلا بٱللهۚ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1568, 67, 75, 'أعوذُ باللهِ السميعِ العليمِ من الشيطانِ الرجيمِ
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (469, 67, 76, 'اللهمَّ بارِكْ فيهِ، ولا تَضُرَّهُ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص240)', '', '', 'اللهم بارك فيه ولا تضره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (470, 67, 77, 'أُعيذُكَ بكلماتِ اللهِ التَّامَّةِ، من كلِّ شيطانٍ وهامَّةٍ، ومن كلِّ عينٍ لامَّةٍ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'أعيذك بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1569, 67, 78, 'وإذا رأى من أخيه ما يُعجِبُه، قال:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'وإذا رأى من أخيه ما يعجبه قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1570, 67, 79, 'اللهمَّ بارِكْ فيهِ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'اللهم بارك فيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1571, 67, 80, 'ويجوز له إذا رأى رجلًا آتاه الله القرآنَ، فهو يتلوه آناءَ الليل، وآناءَ النهار، أو المالَ الذي ينفق منه في سبيل الله، أن يقولَ:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'ويجوز له إذا رأى رجلا آتاه الله القرآن فهو يتلوه آناء الليل وآناء النهار أو المال الذي ينفق منه في سبيل الله أن يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (475, 67, 81, 'لَيتَني أُوتيتُ مِثلَ ما أُوتيَ فلانٌ، فَعَمِلتُ مِثلَ ما يَعمَلُ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'ليتني أوتيت مثل ما أوتي فلان فعملت مثل ما يعمل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1572, 67, 82, 'إذا سَمِعَ صياحَ الدِّيَكَةِ، قال:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'إذا سمع صياح الديكة قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (471, 67, 83, 'اللهمَّ إنِّي أسألُكَ من فضلِكَ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'اللهم إني أسألك من فضلك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1573, 67, 84, 'وإذا سمع نهيقَ الحمير، أو نُباحَ الكلاب بالليل، قال:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'وإذا سمع نهيق الحمير أو نباح الكلاب بالليل قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (472, 67, 85, 'أعوذُ باللهِ السميعِ العليمِ من الشيطانِ الرجيمِ', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'أعوذ بالله السميع العليم من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1574, 67, 86, 'وإذا دَخَلَ بيتًا ليس فيه أحدٌ، قال:', 0, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'وإذا دخل بيتا ليس فيه أحد قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (473, 67, 87, 'السلامُ علينا، وعلى عبادِ اللهِ الصالحين', 1, 'ما يقول إذا أُتِيَ بباكورة الثمر. (ص241)', '', '', 'السلام علينا وعلى عباد الله الصالحين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1575, 67, 88, 'يقول:', 0, 'ما يقول إذا خاف الرياءَ والشِّرْكَ صغيرَه وكبيرَه. (ص242)', '', '', 'يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (474, 67, 89, 'اللهمَّ إنِّي أعوذُ بِكَ أنْ أُشرِكَ بِكَ وأنا أعلمُ، وأستغفرُكَ لما لا أعلمُ', 1, 'ما يقول إذا خاف الرياءَ والشِّرْكَ صغيرَه وكبيرَه. (ص242)', '', '', 'اللهم إني أعوذ بك أن أشرك بك وأنا أعلم وأستغفرك لما لا أعلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1576, 68, 1, 'يستحبُّ أن لا يقومَ من مجلسٍ حتى يدعوَ لنفسه ومَنْ مَعَه، فيقول:', 0, 'دعاء الجالس في جَمْعٍ لنفسِه ومَنْ مَعَهُ. (ص242)', '', '', 'يستحب أن لا يقوم من مجلس حتى يدعو لنفسه ومن معه فيقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (476, 68, 2, 'اللهمَّ اقسِمْ لنا من خشيتِكَ ما تَحولُ بهِ بينَنا وبينَ معاصيكَ، ومن طاعتِكَ ما تُبَلِّغُنا بهِ جنَّتَكَ، ومن اليقينِ ما تُهَوِّنُ بهِ علينا مصائِبَ الدنيا، اللهمَّ مَتِّعْنا بأسماعِنا وأبصارِنا وقوَّتِنا ما أحييْتَنا، واجعَلْهُ الوارثَ مِنَّا، واجعَلْ ثأرَنا على مَنْ ظلَمَنا، وانصُرْنا على مَنْ عادانا، ولا تجعَلْ مُصيبَتَنا في دينِنا، ولا تجعَلِ الدنيا أكبَرَ همِّنا، ولا مَبلَغَ عِلمِنا، ولا تُسَلِّطْ علينا مَنْ لا يرحَمُنا', 1, 'دعاء الجالس في جَمْعٍ لنفسِه ومَنْ مَعَهُ. (ص242–243)', '', '', 'اللهم اقسم لنا من خشيتك ما تحول به بيننا وبين معاصيك ومن طاعتك ما تبلغنا به جنتك ومن اليقين ما تهون به علينا مصائب الدنيا اللهم متعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا واجعله الوارث منا واجعل ثأرنا على من ظلمنا وانصرنا على من عادانا ولا تجعل مصيبتنا في ديننا ولا تجعل الدنيا أكبر همنا ولا مبلغ علمنا ولا تسلط علينا من لا يرحمنا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1577, 68, 3, 'وكان يُعَدُّ لرسولِ الله ﷺ في المجلسِ الواحدِ -قبل أن يقومَ- مِئَةَ مَرَّةٍ:', 0, 'دعاء الجالس في جَمْعٍ لنفسِه ومَنْ مَعَهُ. (ص243)', '', '', 'وكان يعد لرسول الله في المجلس الواحد -قبل أن يقوم- مئة مرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (477, 68, 4, 'رَبِّ اغفِرْ لي، وتُبْ عليَّ، إنَّكَ أنتَ التَّوَّابُ الغَفورُ', 100, 'دعاء الجالس في جَمْعٍ لنفسِه ومَنْ مَعَهُ. (ص243)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1578, 68, 5, 'فإذا تفرَّقوا؛ صَلَّوْا على النبي ﷺ.', 0, 'دعاء الجالس في جَمْعٍ لنفسِه ومَنْ مَعَهُ. (ص243)', '', '', 'فإذا تفرقوا صلوا على النبي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1579, 68, 6, 'وإذا أراد أن يقوم من مجلسٍ، فَلْيَقُل:', 0, 'كفَّارة المجلس. (ص244)', '', '', 'وإذا أراد أن يقوم من مجلس فليقل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (478, 68, 7, 'سبحانَ اللهِ وبحمدِهِ، سبحانَكَ اللهمَّ وبحمدِكَ، أشهَدُ أنْ لا إلهَ إلا أنتَ، أستغفرُكَ، وأتوبُ إليكَ', 1, 'كفَّارة المجلس. (ص244)', '', '', 'سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (479, 68, 8, 'وعن أبي مدينة الدارمي قال: «كان الرجلان من أصحاب النبي ﷺ إذا التقيا؛ لم يتفرَّقا حتى يقرأَ أحدُهما على الآخر: ﴿ وَٱلۡعَصۡرِ ١ إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ ﴾ [سورة العصر]، ثم يُسَلِّم أحدُهما على الآخر».', 0, 'كفَّارة المجلس. (ص244)
